"use client";
/* Token, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Token(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("token"); }, []);
  return React.createElement("piix-sprite", { "name": "token", ...piixAttrs(props) });
}

export default Token;
